    for (final entry in raw.entries)
      if (entry.key.toString().trim().isNotEmpty)
        entry.key.toString().trim(): AdminOrderControlState.fromRaw(
          entry.value is Map ? (entry.value as Map)['state'] : entry.value,
        ),
  };
}

